import React from 'react';
import { Mic, MicOff, Video, VideoOff, PhoneOff, Volume2, VolumeX, Settings } from 'lucide-react';

const VideoControls = ({ 
  isMicOn, 
  isVideoOn, 
  isAudioOn,
  onToggleMic, 
  onToggleVideo, 
  onToggleAudio,
  onEndCall,
  disabled = false 
}) => {
  return (
    <div className="bg-gray-900 bg-opacity-90 backdrop-blur-sm px-6 py-4 rounded-xl shadow-2xl">
      <div className="flex items-center justify-center gap-4">
        {/* Microphone Control */}
        <button
          onClick={onToggleMic}
          disabled={disabled}
          className={`p-4 rounded-full transition-all transform hover:scale-110 ${
            isMicOn 
              ? 'bg-gray-700 hover:bg-gray-600 text-white' 
              : 'bg-red-500 hover:bg-red-600 text-white'
          } disabled:opacity-50 disabled:cursor-not-allowed`}
          title={isMicOn ? 'Mute Microphone' : 'Unmute Microphone'}
        >
          {isMicOn ? (
            <Mic className="w-6 h-6" />
          ) : (
            <MicOff className="w-6 h-6" />
          )}
        </button>

        {/* Video Control */}
        <button
          onClick={onToggleVideo}
          disabled={disabled}
          className={`p-4 rounded-full transition-all transform hover:scale-110 ${
            isVideoOn 
              ? 'bg-gray-700 hover:bg-gray-600 text-white' 
              : 'bg-red-500 hover:bg-red-600 text-white'
          } disabled:opacity-50 disabled:cursor-not-allowed`}
          title={isVideoOn ? 'Turn Off Camera' : 'Turn On Camera'}
        >
          {isVideoOn ? (
            <Video className="w-6 h-6" />
          ) : (
            <VideoOff className="w-6 h-6" />
          )}
        </button>

        {/* Audio Control */}
        <button
          onClick={onToggleAudio}
          disabled={disabled}
          className={`p-4 rounded-full transition-all transform hover:scale-110 ${
            isAudioOn 
              ? 'bg-gray-700 hover:bg-gray-600 text-white' 
              : 'bg-orange-500 hover:bg-orange-600 text-white'
          } disabled:opacity-50 disabled:cursor-not-allowed`}
          title={isAudioOn ? 'Mute AI Voice' : 'Unmute AI Voice'}
        >
          {isAudioOn ? (
            <Volume2 className="w-6 h-6" />
          ) : (
            <VolumeX className="w-6 h-6" />
          )}
        </button>

        {/* End Call */}
        <button
          onClick={onEndCall}
          disabled={disabled}
          className="p-4 rounded-full bg-red-600 hover:bg-red-700 text-white transition-all transform hover:scale-110 disabled:opacity-50 disabled:cursor-not-allowed"
          title="End Interview"
        >
          <PhoneOff className="w-6 h-6" />
        </button>
      </div>

      {/* Status Indicators */}
      <div className="flex items-center justify-center gap-4 mt-3">
        <div className="flex items-center gap-2">
          <div className={`w-2 h-2 rounded-full ${isMicOn ? 'bg-green-500' : 'bg-red-500'}`} />
          <span className="text-xs text-white">
            {isMicOn ? 'Mic On' : 'Mic Off'}
          </span>
        </div>

        <div className="flex items-center gap-2">
          <div className={`w-2 h-2 rounded-full ${isVideoOn ? 'bg-green-500' : 'bg-red-500'}`} />
          <span className="text-xs text-white">
            {isVideoOn ? 'Camera On' : 'Camera Off'}
          </span>
        </div>

        <div className="flex items-center gap-2">
          <div className={`w-2 h-2 rounded-full ${isAudioOn ? 'bg-green-500' : 'bg-orange-500'}`} />
          <span className="text-xs text-white">
            {isAudioOn ? 'AI Audio On' : 'AI Audio Off'}
          </span>
        </div>
      </div>
    </div>
  );
};

export default VideoControls;
